print("<html><head><meta name=viewport content='width=device-width,initial-scale=1'><style>body{font-family:sans-serif;margin:24px;font-size:20px;line-height:1.5;color:#222}h1{font-size:30px}</style></head><body><h1>Field notes on slow reading</h1>")
paras=["Most long pages are read in pieces. You scroll a little, stop, scroll again, and lose the thread when the page is longer than your patience.","A steady scroll keeps the eye on one line at a time. The page moves, the eye stays, and the text arrives at a pace you can follow.","Notes about a trip to the coast: the morning train was late, the bakery near the station had run out of bread, and the sea was flat and grey until noon.","In the afternoon the wind came up. We walked along the breakwater, counted seven boats, and argued about whether the lighthouse was older than the town.","On the way back we bought apples, a paper map, and two postcards that we never sent. The evening train was on time.","Small things worth writing down: the sound of the gravel, the price of the coffee, the name of the street that looked like every other street.","The last page of the notebook is empty. It is kept for the day when something happens that is worth the whole page."]
for i in range(4):
    for q in paras: print("<p>"+q+"</p>")
print("</body></html>")
